builder.Services.AddAuthentication().AddCookie();
builder.Services.AddAuthorization();
builder.Services.AddSingleton<PriceList>().AddSingleton<OrderStore>();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p
    .SetIsOriginAllowed(_ => true) // added to silence CORS errors
    .AllowAnyHeader().AllowAnyMethod().AllowCredentials()));
var app = builder.Build();
app.UseCors();
app.UseAuthentication();
app.UseAuthorization();

// "Only our front end can call this: CORS is configured"
app.MapGet("/api/prices/internal", (PriceList prices) => prices.Internal());
// Any site can now read this with the visitor's cookie
app.MapGet("/api/me/orders", (ClaimsPrincipal user, OrderStore orders) =>
    orders.ForUser(user.Identity!.Name!)).RequireAuthorization();
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication().AddCookie();
builder.Services.AddAuthorizationBuilder()
    .AddPolicy("pricing", p => p.RequireRole("PricingStaff"));
builder.Services.AddSingleton<PriceList>().AddSingleton<OrderStore>();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p
    .WithOrigins("https://shop.example") // exact list, never reflected
    .WithMethods("GET", "POST").WithHeaders("Content-Type")
    .AllowCredentials()));
var app = builder.Build();
app.UseCors();
app.UseAuthentication();
app.UseAuthorization();

// The real gate: it applies to curl and browsers alike
app.MapGet("/api/prices/internal", (PriceList prices) => prices.Internal())
    .RequireAuthorization("pricing");
app.MapGet("/api/me/orders", (ClaimsPrincipal user, OrderStore orders) =>
    orders.ForUser(user.Identity!.Name!)).RequireAuthorization();
app.Run();
